23	/**
24	 * Options for building bubblewrap (bwrap) arguments.
25	 */
26	export interface BwrapArgsOptions {
27	  workspace: string;
28	  workspaceWrite: boolean;
29	  networkAccess: boolean;
30	  allowedPaths: string[];
31	  forbiddenPaths: string[];
32	  additionalPermissions: SandboxPermissions;
33	  includeDirectories: string[];
34	  maskFilePath: string;
35	  isWriteCommand: boolean;
36	}
