38	/**
39	 * Builds the list of bubblewrap arguments based on the provided options.
40	 */
41	export async function buildBwrapArgs(
42	  options: BwrapArgsOptions,
43	): Promise<string[]> {
44	  const bwrapArgs: string[] = [
45	    '--unshare-all',
46	    '--new-session', // Isolate session
47	    '--die-with-parent', // Prevent orphaned runaway processes
48	  ];
49	
50	  if (options.networkAccess || options.additionalPermissions.network) {
51	    bwrapArgs.push('--share-net');
52	  }
53	
54	  bwrapArgs.push(
55	    '--ro-bind',
56	    '/',
57	    '/',
58	    '--dev', // Creates a safe, minimal /dev (replaces --dev-bind)
59	    '/dev',
60	    '--proc', // Creates a fresh procfs for the unshared PID namespace
61	    '/proc',
62	    '--tmpfs', // Provides an isolated, writable /tmp directory
63	    '/tmp',
64	  );
65	
66	  const workspacePath = tryRealpath(options.workspace);
67	
68	  const bindFlag = options.workspaceWrite ? '--bind-try' : '--ro-bind-try';
69	
70	  if (options.workspaceWrite) {
71	    bwrapArgs.push('--bind-try', options.workspace, options.workspace);
72	    if (workspacePath !== options.workspace) {
73	      bwrapArgs.push('--bind-try', workspacePath, workspacePath);
74	    }
75	  } else {
76	    bwrapArgs.push('--ro-bind-try', options.workspace, options.workspace);
77	    if (workspacePath !== options.workspace) {
78	      bwrapArgs.push('--ro-bind-try', workspacePath, workspacePath);
79	    }
80	  }
81	
82	  const { worktreeGitDir, mainGitDir } = resolveGitWorktreePaths(workspacePath);
83	  if (worktreeGitDir) {
84	    bwrapArgs.push(bindFlag, worktreeGitDir, worktreeGitDir);
85	  }
86	  if (mainGitDir) {
87	    bwrapArgs.push(bindFlag, mainGitDir, mainGitDir);
88	  }
89	
90	  const includeDirs = sanitizePaths(options.includeDirectories);
91	  for (const includeDir of includeDirs) {
92	    try {
93	      const resolved = tryRealpath(includeDir);
94	      bwrapArgs.push('--ro-bind-try', resolved, resolved);
95	    } catch {
96	      // Ignore
97	    }
98	  }
99	
100	  const normalizedWorkspace = normalize(workspacePath).replace(/\/$/, '');
101	  for (const allowedPath of options.allowedPaths) {
102	    const resolved = tryRealpath(allowedPath);
103	    if (!fs.existsSync(resolved)) {
104	      // If the path doesn't exist, we still want to allow access to its parent
105	      // if it's explicitly allowed, to enable creating it.
106	      try {
107	        const resolvedParent = tryRealpath(dirname(resolved));
108	        bwrapArgs.push(
109	          options.isWriteCommand ? '--bind-try' : bindFlag,
110	          resolvedParent,
111	          resolvedParent,
112	        );
113	      } catch {
114	        // Ignore
115	      }
116	      continue;
117	    }
118	    const normalizedAllowedPath = normalize(resolved).replace(/\/$/, '');
119	    if (normalizedAllowedPath !== normalizedWorkspace) {
120	      bwrapArgs.push('--bind-try', resolved, resolved);
121	    }
122	  }
123	
124	  const additionalReads = sanitizePaths(
125	    options.additionalPermissions.fileSystem?.read,
126	  );
127	  for (const p of additionalReads) {
128	    try {
129	      const safeResolvedPath = tryRealpath(p);
130	      bwrapArgs.push('--ro-bind-try', safeResolvedPath, safeResolvedPath);
131	    } catch (e: unknown) {
132	      debugLogger.warn(e instanceof Error ? e.message : String(e));
133	    }
134	  }
135	
136	  const additionalWrites = sanitizePaths(
137	    options.additionalPermissions.fileSystem?.write,
138	  );
139	  for (const p of additionalWrites) {
140	    try {
141	      const safeResolvedPath = tryRealpath(p);
142	      bwrapArgs.push('--bind-try', safeResolvedPath, safeResolvedPath);
143	    } catch (e: unknown) {
144	      debugLogger.warn(e instanceof Error ? e.message : String(e));
145	    }
146	  }
147	
148	  for (const file of GOVERNANCE_FILES) {
149	    const filePath = join(options.workspace, file.path);
150	    const realPath = tryRealpath(filePath);
151	    bwrapArgs.push('--ro-bind', filePath, filePath);
152	    if (realPath !== filePath) {
153	      bwrapArgs.push('--ro-bind', realPath, realPath);
154	    }
155	  }
156	
157	  for (const p of options.forbiddenPaths) {
158	    let resolved: string;
159	    try {
160	      resolved = tryRealpath(p); // Forbidden paths should still resolve to block the real path
161	      if (!fs.existsSync(resolved)) continue;
162	    } catch (e: unknown) {
163	      debugLogger.warn(
164	        `Failed to resolve forbidden path ${p}: ${e instanceof Error ? e.message : String(e)}`,
165	      );
166	      bwrapArgs.push('--ro-bind', '/dev/null', p);
167	      continue;
168	    }
169	    try {
170	      const stat = fs.statSync(resolved);
171	      if (stat.isDirectory()) {
172	        bwrapArgs.push('--tmpfs', resolved, '--remount-ro', resolved);
173	      } else {
174	        bwrapArgs.push('--ro-bind', '/dev/null', resolved);
175	      }
176	    } catch (e: unknown) {
177	      if (isErrnoException(e) && e.code === 'ENOENT') {
178	        bwrapArgs.push('--symlink', '/dev/null', resolved);
179	      } else {
180	        debugLogger.warn(
181	          `Failed to stat forbidden path ${resolved}: ${e instanceof Error ? e.message : String(e)}`,
182	        );
183	        bwrapArgs.push('--ro-bind', '/dev/null', resolved);
184	      }
185	    }
186	  }
187	
188	  // Mask secret files (.env, .env.*)
189	  const secretArgs = await getSecretFilesArgs(
190	    options.workspace,
191	    options.allowedPaths,
192	    options.maskFilePath,
193	  );
194	  bwrapArgs.push(...secretArgs);
195	
196	  return bwrapArgs;
197	}
