202	/**
203	 * Checks if a given file name matches any of the secret file patterns.
204	 */
205	export function isSecretFile(fileName: string): boolean {
206	  return SECRET_FILES.some((s) => {
207	    if (s.pattern.endsWith('*')) {
208	      const prefix = s.pattern.slice(0, -1);
209	      return fileName.startsWith(prefix);
210	    }
211	    return fileName === s.pattern;
212	  });
213	}
