43	let cachedBpfPath: string | undefined;
44	
45	function getSeccompBpfPath(): string {
46	  if (cachedBpfPath) return cachedBpfPath;
47	
48	  const arch = os.arch();
49	  let AUDIT_ARCH: number;
50	  let SYS_ptrace: number;
51	
52	  if (arch === 'x64') {
53	    AUDIT_ARCH = 0xc000003e; // AUDIT_ARCH_X86_64
54	    SYS_ptrace = 101;
55	  } else if (arch === 'arm64') {
56	    AUDIT_ARCH = 0xc00000b7; // AUDIT_ARCH_AARCH64
57	    SYS_ptrace = 117;
58	  } else if (arch === 'arm') {
59	    AUDIT_ARCH = 0x40000028; // AUDIT_ARCH_ARM
60	    SYS_ptrace = 26;
61	  } else if (arch === 'ia32') {
62	    AUDIT_ARCH = 0x40000003; // AUDIT_ARCH_I386
63	    SYS_ptrace = 26;
64	  } else {
65	    throw new Error(`Unsupported architecture for seccomp filter: ${arch}`);
66	  }
67	
68	  const EPERM = 1;
69	  const SECCOMP_RET_KILL_PROCESS = 0x80000000;
70	  const SECCOMP_RET_ERRNO = 0x00050000;
71	  const SECCOMP_RET_ALLOW = 0x7fff0000;
72	
73	  const instructions = [
74	    { code: 0x20, jt: 0, jf: 0, k: 4 }, // Load arch
75	    { code: 0x15, jt: 1, jf: 0, k: AUDIT_ARCH }, // Jump to kill if arch != native arch
76	    { code: 0x06, jt: 0, jf: 0, k: SECCOMP_RET_KILL_PROCESS }, // Kill
77	
78	    { code: 0x20, jt: 0, jf: 0, k: 0 }, // Load nr
79	    { code: 0x15, jt: 0, jf: 1, k: SYS_ptrace }, // If ptrace, jump to ERRNO
80	    { code: 0x06, jt: 0, jf: 0, k: SECCOMP_RET_ERRNO | EPERM }, // ERRNO
81	
82	    { code: 0x06, jt: 0, jf: 0, k: SECCOMP_RET_ALLOW }, // Allow
83	  ];
84	
85	  const buf = Buffer.alloc(8 * instructions.length);
86	  for (let i = 0; i < instructions.length; i++) {
87	    const inst = instructions[i];
88	    const offset = i * 8;
89	    buf.writeUInt16LE(inst.code, offset);
90	    buf.writeUInt8(inst.jt, offset + 2);
91	    buf.writeUInt8(inst.jf, offset + 3);
92	    buf.writeUInt32LE(inst.k, offset + 4);
93	  }
94	
95	  const tempDir = fs.mkdtempSync(join(os.tmpdir(), 'gemini-cli-seccomp-'));
96	  const bpfPath = join(tempDir, 'seccomp.bpf');
97	  fs.writeFileSync(bpfPath, buf);
98	  cachedBpfPath = bpfPath;
99	
100	  // Cleanup on exit
101	  process.on('exit', () => {
102	    try {
103	      fs.rmSync(tempDir, { recursive: true, force: true });
104	    } catch {
105	      // Ignore errors
106	    }
107	  });
108	
109	  return bpfPath;
110	}
