115	function touch(filePath: string, isDirectory: boolean) {
116	  assertValidPathString(filePath);
117	  try {
118	    // If it exists (even as a broken symlink), do nothing
119	    if (fs.lstatSync(filePath)) return;
120	  } catch {
121	    // Ignore ENOENT
122	  }
123	
124	  if (isDirectory) {
125	    fs.mkdirSync(filePath, { recursive: true });
126	  } else {
127	    fs.mkdirSync(dirname(filePath), { recursive: true });
128	    fs.closeSync(fs.openSync(filePath, 'a'));
129	  }
130	}
