187	  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
188	    const isReadonlyMode = this.options.modeConfig?.readonly ?? true;
189	    const allowOverrides = this.options.modeConfig?.allowOverrides ?? true;
190	
191	    verifySandboxOverrides(allowOverrides, req.policy);
192	
193	    let command = req.command;
194	    let args = req.args;
195	
