11	export function isErrnoException(e: unknown): e is NodeJS.ErrnoException {
12	  return e instanceof Error && 'code' in e;
13	}
14	
15	export function tryRealpath(p: string): string {
16	  assertValidPathString(p);
17	  try {
18	    return fs.realpathSync(p);
19	  } catch (e) {
20	    if (isErrnoException(e) && e.code === 'ENOENT') {
21	      const parentDir = path.dirname(p);
22	      if (parentDir === p) {
23	        return p;
24	      }
25	      return path.join(tryRealpath(parentDir), path.basename(p));
26	    }
27	    throw e;
28	  }
29	}
