  const { resolvedPaths } = options;

  const bwrapArgs: string[] = [
    '--unshare-all',
    '--new-session', // Isolate session
    '--die-with-parent', // Prevent orphaned runaway processes
  ];

  if (options.networkAccess) {
    bwrapArgs.push('--share-net');
  }

  bwrapArgs.push(
    '--ro-bind',
    '/',
    '/',
    '--dev', // Creates a safe, minimal /dev (replaces --dev-bind)
    '/dev',
    '--proc', // Creates a fresh procfs for the unshared PID namespace
    '/proc',
    '--tmpfs', // Provides an isolated, writable /tmp directory
    '/tmp',
  );

  const originalWorkspace = resolvedPaths.workspace.original;
  const resolvedWorkspace = resolvedPaths.workspace.resolved;

  const bindFlag = options.workspaceWrite ? '--bind-try' : '--ro-bind-try';

  // Bind-mount the workspace directory using its original (as-provided) path.
  bwrapArgs.push(bindFlag, originalWorkspace, originalWorkspace);
  if (resolvedWorkspace !== originalWorkspace) {
    bwrapArgs.push(bindFlag, resolvedWorkspace, resolvedWorkspace);
  }

  const { worktreeGitDir, mainGitDir } =
    resolveGitWorktreePaths(resolvedWorkspace);
  if (worktreeGitDir) {
    bwrapArgs.push(bindFlag, worktreeGitDir, worktreeGitDir);
  }
  if (mainGitDir) {
    bwrapArgs.push(bindFlag, mainGitDir, mainGitDir);
  }

  // Directories included globally are made available read-only.
  for (const includeDir of resolvedPaths.globalIncludes) {
    bwrapArgs.push('--ro-bind-try', includeDir, includeDir);
  }

  const workspaceIdentities = new Set([
    normalizePath(originalWorkspace),
    normalizePath(resolvedWorkspace),
  ]);

  // Paths explicitly permitted for writing, and paths allowed by policy, are
  // bound read-write. For paths that do not yet exist we bind their parent
  // directory so the file can be created.
  for (const allowedPath of [
    ...resolvedPaths.policyWrite,
    ...resolvedPaths.policyAllowed,
  ]) {
    if (workspaceIdentities.has(normalizePath(allowedPath))) {
      continue;
